require("Game.Views.ItemViews.IndexCommonItem")
IndexCommon = class("IndexCommon")

function IndexCommon:ctor()
end

function IndexCommon:InitPanel(gameObject)
    self.gameObject = gameObject;
    self.transform = gameObject.transform;
    self:FindComponent(self.transform);
    EventDelegate.Add(self.but_left.onClick,EventDelegate.Callback(function() self:ButLeftClick() end));
    EventDelegate.Add(self.but_right.onClick,EventDelegate.Callback(function() self:ButRightClick() end));
    IndexCommon:Reset()
end
function IndexCommon:Reset()
    self.usedItemList = {};
    self.recycledItemList = {};
    self.indexCommonCallback = nil;
    self.data = nil;
    self.titleIndex = 1;
end

function IndexCommon:ButLeftClick()
    self:ChangeTitleIndex(self.titleIndex - 1);
end

function IndexCommon:ButRightClick()
    self:ChangeTitleIndex(self.titleIndex + 1);
end

function IndexCommon:FindComponent(transform)
    local tTransform = transform;
    self.but_left = Util.FindChildEx(tTransform,"leftButton"):GetComponent("UIEventTrigger");
    self.but_right = Util.FindChildEx(tTransform,"rightButton"):GetComponent("UIEventTrigger");
    self.lab_sortClass = Util.FindChildEx(tTransform,"lab_sortClass"):GetComponent("UILabel");
    self.scrollView = Util.FindChildEx(tTransform,"OptionList"):GetComponent("UIScrollView");
    self.grid = Util.FindChildEx(tTransform,"OptionList/Grid"):GetComponent("UIGrid");
    self.recovery = Util.FindChildEx(tTransform,"recovery");
    self.obj_item = Util.FindChildEx(tTransform,"recovery/Option").gameObject;
end

function IndexCommon:Init(data, indexCommonCallback)
    if data == nil or #data == 0 then
        print("此处 data 不应为 nil 或 空表")
        return;
    end
    self.data = data;
    self.indexCommonCallback = indexCommonCallback;
    self:ChangeTitleIndex(1);
end

function IndexCommon:SetItemList(data)
    self.lab_sortClass.text = data.title;
    PrefabTool.AdjustPrefabItemCount(#data.itemList, self.recovery, self.grid.transform,
            self.usedItemList, self.recycledItemList, self.obj_item, IndexCommonItem);
    for i = 1, #self.usedItemList do
        self.usedItemList[i]:Init(data.itemList[i], function(index) self:ItemOnClick(index) end);
    end
    self.grid:Reposition();
    self.scrollView:ResetPosition();
end

function IndexCommon:ItemOnClick(index)
    for i = 1, #self.usedItemList do
        self.usedItemList[i]:ChangeState(false)
    end
    self.usedItemList[index]:ChangeState(true)
    if self.indexCommonCallback then
        self.indexCommonCallback(self.data[self.titleIndex].tag, index);
    end
end

function IndexCommon:ChangeTitleIndex(newIndex)
    if newIndex == nil then
        newIndex = 1;
    elseif newIndex < 0 then
        newIndex = 0;
    end
    local dataCount = #self.data;
    local index = newIndex % dataCount;
    if index == 0 then
        index = dataCount;
    end
    self.titleIndex = index;
    self:SetItemList(self.data[self.titleIndex]);
    for i = 1, #self.usedItemList do
        self.usedItemList[i]:ChangeState(false)
    end
    self.usedItemList[1]:ChangeState(true)
    if self.indexCommonCallback then
        self.indexCommonCallback(self.data[self.titleIndex].tag, 1);
    end
end